package org.marketreview.nativeapp;
import android.content.Context;import android.view.*;import android.widget.*;import java.util.*;import org.json.*;
final class AuctionAnalysisScreen extends LinearLayout {
 interface Snapshots{JSONArray current()throws Exception;}interface Work{void run()throws Exception;}
 final Snapshots provider;final FrameLayout frame;final ScrollView main,analysis,raw;final LinearLayout list,data;final TextView status,summary,reader,sourceNote;Runnable requestReload;final EditText search;final Spinner section;final Map<String,Spinner> filters=new LinkedHashMap<>();final Map<String,List<String>> options=new LinkedHashMap<>();final Map<String,String> selected=new LinkedHashMap<>();final Button previous,next;JSONArray snapshots=new JSONArray(),matched=new JSONArray(),items=new JSONArray();JSONObject captured=new JSONObject(),result=new JSONObject(),sourceEvidence=new JSONObject();int listPage=0,dataPage=0,view=0,sectionIndex=0,readerBack=1;boolean loading=false,dark;
 AuctionAnalysisScreen(Context c,Snapshots provider){super(c);setOrientation(VERTICAL);this.provider=provider;sourceNote=new TextView(c);sourceNote.setMaxLines(4);addView(sourceNote);frame=new FrameLayout(c);addView(frame,new LayoutParams(-1,0,1));status=new TextView(c);addView(status);main=new ScrollView(c);LinearLayout l=layout(main);TextView title=new TextView(c);title.setText("集合竞价八形态 / 历史覆盖 · 本机研究观察，非实时或收益承诺");l.addView(title);search=new EditText(c);search.setHint("完整证券身份、快照或来源搜索");l.addView(search);String[] keys={"instrumentId","date","phase"},labels={"证券","历史日期","开盘/收盘阶段"};for(int i=0;i<keys.length;i++){String key=keys[i];TextView label=new TextView(c);label.setText(labels[i]);l.addView(label);Spinner s=new Spinner(c);l.addView(s);filters.put(key,s);options.put(key,new ArrayList<>());selected.put(key,"");s.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?>p){}public void onItemSelected(AdapterView<?>p,View v,int index,long id){if(!loading&&index==s.getSelectedItemPosition()){List<String> values=options.get(key);if(index>=0&&index<values.size()&&!values.get(index).equals(selected.get(key))){selected.put(key,values.get(index));listPage=0;guard(()->render());}}}});}list=new LinearLayout(c);list.setOrientation(VERTICAL);l.addView(list);button(l,"快照上一页",()->{if(listPage>0)listPage--;render();});button(l,"快照下一页",()->{if((listPage+1)*20<matched.length())listPage++;render();});button(l,"重读本机竞价归档",()->{if(requestReload!=null)requestReload.run();else refresh();});reader=new TextView(c);reader.setTextIsSelectable(true);button(l,"来源读取完整说明",()->{reader.setText(SourceAnalysisPacket.json(sourceEvidence));readerBack=0;show(2);});analysis=new ScrollView(c);LinearLayout d=layout(analysis);button(d,"返回快照筛选",()->show(0));summary=new TextView(c);d.addView(summary);section=new Spinner(c);section.setAdapter(new ArrayAdapter<String>(c,android.R.layout.simple_spinner_dropdown_item,new String[]{"完整原点审计","历史资格/日期审计","八形态规则与理由","本次形态与证据"}));d.addView(section);data=new LinearLayout(c);data.setOrientation(VERTICAL);d.addView(data);previous=button(d,"原点/历史上一页",()->{if(dataPage>0)dataPage--;renderData();});next=button(d,"原点/历史下一页",()->{if((dataPage+1)*20<items.length())dataPage++;renderData();});button(d,"完整缺口/阈值/原始输入",()->{readerBack=1;reader.setText(AuctionAnalysisModel.detail(result));show(2);});raw=new ScrollView(c);LinearLayout r=layout(raw);button(r,"返回上一子页",()->show(readerBack));r.addView(reader);section.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?>p){}public void onItemSelected(AdapterView<?>p,View v,int index,long id){if(!loading&&index==section.getSelectedItemPosition()&&sectionIndex!=index){sectionIndex=index;dataPage=0;guard(()->renderData());}}});search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int d){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int a,int b,int d){if(!loading){listPage=0;guard(()->render());}}});show(0);guard(()->refresh());}
 LinearLayout layout(ScrollView s){LinearLayout l=new LinearLayout(getContext());l.setOrientation(VERTICAL);s.addView(l);return l;}Button button(LinearLayout l,String title,Work work){Button b=new Button(getContext());b.setText(title);l.addView(b);b.setOnClickListener(v->guard(work));return b;}void guard(Work w){try{w.run();}catch(Exception e){status.setText(e.getMessage());}}
 String pointSummary(JSONObject r){String[] keys={"auctionReferencePrice","auctionMatchedVolume","auctionUnmatchedBuyVolume","auctionUnmatchedSellVolume"};String[] values=new String[4];for(int i=0;i<4;i++)values[i]=r.opt(keys[i]) instanceof Number?String.valueOf(r.opt(keys[i])):"未知";return "参考价 "+values[0]+" · 匹配 "+values[1]+" 股\n未匹配买/卖 "+values[2]+" / "+values[3]+" 股";}
 String field(JSONObject s,String key){String value=key.equals("instrumentId")?s.optString(key):AuctionAnalysisModel.obj(s,"input").optString(key);return value.isEmpty()?"未知":value;}
 void refresh()throws Exception{SourceAnalysisPacket.require(provider!=null,"宿主未注入竞价快照，不能生成形态");JSONArray candidate=provider.current();Set<String> ids=new HashSet<>();for(int i=0;i<candidate.length();i++){JSONObject s=candidate.getJSONObject(i);SourceAnalysisPacket.require(s.opt("id") instanceof String&&!s.optString("id").isEmpty()&&ids.add(s.getString("id")),"快照身份缺失或重复");}snapshots=new JSONArray();for(int i=0;i<candidate.length();i++)snapshots.put(new JSONObject(SourceAnalysisPacket.json(candidate.getJSONObject(i))));loading=true;for(String key:filters.keySet()){TreeSet<String> values=new TreeSet<>();for(int i=0;i<snapshots.length();i++)values.add(field(snapshots.getJSONObject(i),key));List<String> list=options.get(key);list.clear();list.add("");list.addAll(values);List<String> labels=new ArrayList<>(list);labels.set(0,"全部");filters.get(key).setAdapter(new ArrayAdapter<String>(getContext(),android.R.layout.simple_spinner_dropdown_item,labels));int index=list.indexOf(selected.get(key));selected.put(key,index<0?"":list.get(index));filters.get(key).setSelection(index<0?0:index);}loading=false;render();}
 void render()throws Exception{matched=new JSONArray();for(int i=0;i<snapshots.length();i++){JSONObject s=snapshots.getJSONObject(i);boolean match=true;for(String key:selected.keySet())if(!selected.get(key).isEmpty()&&!selected.get(key).equals(field(s,key)))match=false;if(match&&(search.getText().toString().isEmpty()||SourceAnalysisPacket.json(s).toLowerCase(Locale.ROOT).contains(search.getText().toString().toLowerCase(Locale.ROOT))))matched.put(s);}listPage=Math.max(0,Math.min(listPage,Math.max(0,(matched.length()-1)/20)));list.removeAllViews();for(int i=listPage*20;i<Math.min(matched.length(),(listPage+1)*20);i++){JSONObject s=matched.getJSONObject(i);button(list,s.optString("id")+" · "+field(s,"instrumentId")+" · "+field(s,"date")+" · "+field(s,"phase"),()->choose(s));}status.setText("本机提供"+snapshots.length()+"个快照 · 匹配"+matched.length()+" · 第"+(listPage+1)+"/"+Math.max(1,(matched.length()+19)/20)+"页；无新采集");SourceHandoffPanel.styleTree(list,dark);}
 void choose(JSONObject s)throws Exception{captured=new JSONObject(SourceAnalysisPacket.json(s));result=AuctionAnalysisModel.analyze(captured);summary.setText("证券："+captured.optString("instrumentId")+" · 日期："+field(captured,"date")+" · 阶段："+field(captured,"phase")+"\n截至："+AuctionAnalysisModel.obj(captured,"input").optString("asOf")+"\n状态："+result.optString("patternStatus")+" · "+result.optString("reason")+"\n历史资格："+(result.optString("dataLevel").equals("D0")?"未知":result.optInt("historyCount")+"个可用日期")+"（不是历史存在总数）\n来源："+AuctionAnalysisModel.obj(AuctionAnalysisModel.obj(captured,"input"),"meta").optString("sourceId"));dataPage=0;renderData();show(1);}
 void renderData()throws Exception{String key=new String[]{"pointAudit","historyAudit","rules","patterns"}[sectionIndex];items=key.equals("rules")?AuctionAnalysisModel.rules():AuctionAnalysisModel.arr(result,key);if(items.length()==0&&(key.equals("pointAudit")||key.equals("historyAudit"))){JSONArray originals=AuctionAnalysisModel.arr(AuctionAnalysisModel.obj(captured,"input"),key.equals("pointAudit")?"rows":"history");items=new JSONArray();for(int i=0;i<originals.length();i++)items.put(new JSONObject().put("original",originals.get(i)).put("reason","契约或当前时刻不足；仅保留原数据，资格未知"));}dataPage=Math.max(0,Math.min(dataPage,Math.max(0,(items.length()-1)/20)));data.removeAllViews();for(int i=dataPage*20;i<Math.min(items.length(),(dataPage+1)*20);i++){JSONObject item=items.getJSONObject(i),original=AuctionAnalysisModel.obj(item,"original");String label=item.optString("label");if(label.isEmpty())label=original.optString("date")+" "+original.optString("time")+" "+original.optString("clock")+" · "+item.optString("reason")+item.optString("excludedReason");if(key.equals("pointAudit"))label+="\n"+pointSummary(original);button(data,(i+1)+" · "+label,()->{readerBack=1;reader.setText(SourceAnalysisPacket.json(item));show(2);});}previous.setEnabled(dataPage>0);next.setEnabled((dataPage+1)*20<items.length());status.setText("完整记录"+items.length()+" · 第"+(dataPage+1)+"/"+Math.max(1,(items.length()+19)/20)+"页；普通报价无指示价/虚拟量就保持未知");SourceHandoffPanel.styleTree(data,dark);}
 void show(int index){view=index;frame.removeAllViews();frame.addView(index==0?main:index==1?analysis:raw,new FrameLayout.LayoutParams(-1,-1));SourceHandoffPanel.styleTree(frame,dark);}boolean back(){if(view==0)return false;show(view==2?readerBack:0);return true;}void setDarkTheme(boolean dark){this.dark=dark;SourceHandoffPanel.styleTree(this,dark);}
 JSONObject saveState()throws Exception{JSONObject q=new JSONObject();for(String k:selected.keySet())q.put(k,selected.get(k));return new JSONObject().put("filters",q).put("search",search.getText().toString()).put("listPage",listPage).put("dataPage",dataPage).put("captured",captured).put("result",result).put("section",sectionIndex).put("view",view).put("reader",reader.getText().toString()).put("readerBack",readerBack).put("readerScroll",raw.getScrollY());}
 void restoreState(JSONObject input)throws Exception{JSONObject s=new JSONObject(SourceAnalysisPacket.json(input));loading=true;JSONObject q=AuctionAnalysisModel.obj(s,"filters");search.setText(s.optString("search"));for(String k:filters.keySet()){int index=options.get(k).indexOf(q.optString(k));selected.put(k,index<0?"":options.get(k).get(index));filters.get(k).setSelection(index<0?0:index);}listPage=Math.max(0,s.optInt("listPage"));dataPage=Math.max(0,s.optInt("dataPage"));captured=AuctionAnalysisModel.obj(s,"captured");result=AuctionAnalysisModel.obj(s,"result");sectionIndex=Math.max(0,Math.min(3,s.optInt("section")));section.setSelection(sectionIndex);reader.setText(s.optString("reader"));readerBack=s.optInt("readerBack",1)==0?0:1;loading=false;render();renderData();summary.setText("已恢复本机捕获分析（不是实时更新）\n"+result.optString("reason"));show(Math.max(0,Math.min(2,s.optInt("view"))));raw.post(()->raw.scrollTo(0,s.optInt("readerScroll")));}
}
